//! TOTORO mono scan: goldens generated by the cardscan sidecar's own Python
//! (Pillow 12.3 / cv2 5.0.0 / RapidFuzz 3.14.3, image cardscan:local-scanspeed)
//! — see tests/fixtures/scan_ocr. Strip prep must be byte-identical and the
//! title matcher must return the same (name, score) as `find_card_by_ocr`.

use scrybox_server::scan_ocr::{cvresize, names::Oracle, pil::Rgb};
use std::collections::HashSet;
use std::path::PathBuf;

fn fx(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/scan_ocr").join(name)
}

fn load(name: &str) -> Rgb {
    let i = image::open(fx(name)).unwrap().to_rgb8();
    Rgb { w: i.width() as usize, h: i.height() as usize, px: i.into_raw() }
}

#[test]
fn autocontrast_lanczos_and_cv_resize_are_byte_identical() {
    let src = load("src.png");
    let a = src.autocontrast();
    assert_eq!(a, load("autocontrast.png"), "ImageOps.autocontrast");
    for th in [96usize, 128, 160] {
        let tw = ((a.w as f64 * th as f64 / a.h as f64).round_ties_even() as usize).max(64);
        let l = a.resize_lanczos(tw, th);
        assert_eq!(l, load(&format!("lanczos_{th}.png")), "LANCZOS {th}");
        let rw = (48.0 * l.w as f64 / l.h as f64).ceil() as usize;
        assert_eq!(cvresize::resize_linear(&l, rw, 48), load(&format!("cv_{th}.png")), "cv2.resize {th}");
    }
}

#[test]
fn find_card_by_ocr_matches_python() {
    let g: serde_json::Value = serde_json::from_slice(&std::fs::read(fx("names.json")).unwrap()).unwrap();
    let names = g["names"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect();
    let excl: HashSet<String> = g["excluded"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect();
    let o = Oracle::from_names(names, excl);
    for c in g["cases"].as_array().unwrap() {
        let q = c[0].as_str().unwrap();
        let (n, s) = o.find_card_by_ocr(q, 0.90);
        assert_eq!(n.as_deref(), c[1].as_str(), "name for {q:?}");
        assert_eq!(format!("{s:?}"), c[2].as_str().unwrap(), "score for {q:?}");
    }
}
